function strip_quotes(line,    i, n, c, out, j, interior, quote, start) {
    out = ""
    i = 1
    n = length(line)
    while (i <= n) {
        c = substr(line, i, 1)
        if (c == "'" || c == "\"") {
            quote = c
            start = i + 1
            j = start
            if (quote == "\"") {
                while (j <= n) {
                    if (substr(line, j, 1) == "\\" && j < n) {
                        j += 2
                        continue
                    }
                    if (substr(line, j, 1) == quote) break
                    j++
                }
            } else {
                idx = index(substr(line, start), quote)
                j = (idx == 0) ? n + 1 : start + idx - 1
            }
            if (j > n) {
                out = out c
                i++
                continue
            }
            interior = substr(line, start, j - start)
            if (interior ~ /[ \t]/) {
                out = out quote quote
            } else {
                out = out interior
            }
            i = j + 1
            continue
        }
        out = out c
        i++
    }
    return out
}

BEGIN { in_heredoc = 0; delim = ""; strip_tabs = 0 }

{
    line = $0
    if (in_heredoc) {
        test = line
        if (strip_tabs) sub(/^\t+/, "", test)
        if (test == delim) {
            in_heredoc = 0
            delim = ""
            strip_tabs = 0
        }
        next
    }

    if (match(line, /<<-?[[:space:]]*['"]?[A-Za-z_][A-Za-z0-9_]*['"]?/)) {
        op = substr(line, RSTART, RLENGTH)
        before = substr(line, 1, RSTART - 1)
        after = substr(line, RSTART + RLENGTH)
        strip_tabs = (op ~ /^<<-/)
        delimword = op
        sub(/^<<-?[[:space:]]*/, "", delimword)
        gsub(/['"]/, "", delimword)
        delim = delimword
        in_heredoc = 1
        print strip_quotes(before) op strip_quotes(after)
        next
    }

    print strip_quotes(line)
}

