function unescape(s,    i, n, c, out, nc) {
    out = ""
    i = 1
    n = length(s)
    while (i <= n) {
        c = substr(s, i, 1)
        if (c == "\\" && i < n) {
            nc = substr(s, i + 1, 1)
            if (nc == "\"") { out = out "\""; i += 2; continue }
            if (nc == "\\") { out = out "\\"; i += 2; continue }
            if (nc == "/")  { out = out "/";  i += 2; continue }
            if (nc == "n")  { out = out "\n"; i += 2; continue }
            if (nc == "t")  { out = out "\t"; i += 2; continue }
            if (nc == "r")  { out = out "\r"; i += 2; continue }
            out = out c
            i++
            continue
        }
        out = out c
        i++
    }
    return out
}
{ print unescape($0) }
EOF
